    RAISE EXCEPTION 'migration 1898: expected 8 Steve Johnson blanks from 1897 at value 0, found %', n;
  END IF;

  -- Every topic written here must be pinned in Season 2 at the revision used.
  SELECT count(*) INTO n FROM (SELECT DISTINCT topic_id, topic_revision_id FROM (VALUES
    ('00b95a6a-75db-4521-b523-3326bba938de'::uuid, '88858826-90c0-41c9-a3a4-1d9f5b8c5307'::uuid),
