                     AND sq.topic_id = w.topic_id AND sq.topic_revision_id = w.topic_revision_id);
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1898: % written topics are not pinned in Season 2 at the stated revision', n;
  END IF;

  -- The blocked keys ride on `immigration`, which still has NO Season 2 pin.
  SELECT count(*) INTO n FROM inform.season_questions sq JOIN inform.compass_topics t ON t.id = sq.topic_id
