INSERT INTO inform.politician_context
  (politician_id, topic_id, season_id, topic_revision_id, reasoning, sources)
VALUES
  -- Adrian Boafo / public-safety-approach  (Season 1 chair 2 -> blank, NO_INSTRUMENT)
