 WHERE politician_id = '768ac1cf-a599-4ddb-943c-c985fafb2607'::uuid AND topic_id = '669cac97-66a6-4087-b036-936fbe62efb3'::uuid AND season_id = '86d893a1-c1a2-4bbf-b4e5-69ec43221194';

-- Sheree Sample-Hughes / housing -- a Season 2 row already exists at 3; blank it IN PLACE.
UPDATE inform.politician_context SET reasoning = 'Blanked 2026-10-07. 🔴 THE CHAIR RESTS ON NO INSTRUMENT AT ALL. The only source on this row is Sheree Sample-Hughes''s mgaleg roster page (Members/Details/sample01). A roster page states who someone is -- name, party, district, county, committee -- and lists the bills they put their name to. IT CARRIES NO POSITION. The reasoning here names no bill, no vote and no statement; it reaches chair 3 from party, district or role alone ("as a Baltimore City Democrat", "backed progressive revenue measures"). Every bill this member sponsored or co-sponsored in the 2023, 2024, 2025 and 2026 Regular Sessions was read from mgaleg''s own per-session member record (Members/Details/<slug>?ys=<session>), which is mgaleg''s attribution and so is not subject to the surname twin. ⚠ The member page defaults to the CURRENT session only, so each session was fetched explicitly. 101 sponsorships were read across 2023RS, 2024RS, 2025RS, 2026RS and none is named or paraphrased by this row, so there is nothing a reader could check. 🔑 A PARTY IS NOT AN INSTRUMENT -- the same rule that blanked the Morales and Campos redistricting rows in migration 1897. The source examined is kept below so the next reader does not re-derive this from scratch. This is a blank, not a deletion: the chair may well be re-researchable from the member''s actual record, and that is an invitation.', sources = ARRAY['https://mgaleg.maryland.gov/mgawebsite/Members/Details/sample01']::text[], updated_at = now()
